/* Linker version script of libzephyr-java: only the JNI entry points are exported, so the library
   can sit next to monero-java's in one process.
   -fvisibility=hidden leaves the weak std/boost template instantiations visible (libstdc++'s
   visibility pragma, BOOST_SYMBOL_VISIBLE); this list makes everything else local. */
{
  global:
    Java_zephyr_*;
    JNI_OnLoad;
  local:
    *;
};
